<?phpnamespace app\store\controller\shop;use app\store\controller\Controller;use app\store\model\Table as TableModel;use think\facade\View;/** * 餐桌/包间控制器 */class Table extends Controller{     /**     * 列表     */    public function index()    {        $model = new TableModel;        $list = $model->getList();        return View::fetch('index', compact('list'));    }    /**     * 添加     */    public function add()    {        if ($this->request->isPost()) {            $model = new TableModel;            if ($model->add($this->postData('data'))) {                return $this->renderSuccess('添加成功', url('shop.table/index'));            }            $error = $model->getError() ?: '添加失败';            return $this->renderError($error);        }        return redirect(url('shop.table/index'));    }    /**     * 删除     */    public function delete()    {        $data = $this->postData();        $model = TableModel::get($data['id']);        if($model->remove()) {            return $this->renderSuccess('删除成功');        }        $error = $model->getError() ?: '删除失败';        return $this->renderError($error);    }    /**     * 编辑     */    public function edit(int $id)    {        $model = TableModel::get($id);        if ($this->request->isGet()) {            if($model){               return $this->renderSuccess('', '', compact('model'));             }            return $this->renderError('获取失败');        }        // 更新记录        if ($model->edit($this->postData('data'))) {            return $this->renderSuccess('操作成功', url('shop.table/index'));        }        $error = $model->getError() ?: '操作失败';        return $this->renderError($error);    }}